package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;import android.media.AudioManager;import android.net.wifi.WifiManager;import android.widget.*;import java.io.*;import java.util.*;
/** Allowlisted status report; never reads logcat, identifiers, accounts or messages. */
public final class DiagnosticActivity extends LeoActivity {
    private NetworkTelemetry network;private TextView details;private String report="";private boolean refreshing,refreshAgain;
    protected void onCreate(Bundle b){super.onCreate(b);begin("Diagnostic Leo");ScrollView scroll=new ScrollView(this);details=text("Se verifică…",15);scroll.addView(details);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));network=new NetworkTelemetry(this,new Runnable(){public void run(){refresh();}});left=new Runnable(){public void run(){options("Diagnostic",new String[]{"Actualizează","Exportă jurnalul tehnic","Ce conține raportul?"},new Choice(){public void pick(int n){if(n==0)refresh();else if(n==1)export();else notice("Doar baterie, memorie, spațiu, stare rețea și timpi UI. Fără numere, mesaje, conturi, SSID, IP sau identificatori hardware.");}});}};footer("Opțiuni","Derulează","Înapoi");scroll.setFocusable(true);scroll.requestFocus();}
    protected void onResume(){super.onResume();network.start();refresh();}
    protected void onPause(){network.stop();super.onPause();}
    private void refresh(){if(network==null||details==null)return;if(refreshing){refreshAgain=true;return;}refreshing=true;final String sims=network.summary();worker.execute(new Runnable(){public void run(){final String status=collect(DiagnosticActivity.this,sims);ui(new Runnable(){public void run(){report=status;details.setText(status);refreshing=false;if(refreshAgain){refreshAgain=false;refresh();}}});}});}
    static String collect(Context c,String sims){StringBuilder text=new StringBuilder("LEO · JURNAL TEHNIC\n");text.append("Android ").append(Build.VERSION.RELEASE).append(" · API ").append(Build.VERSION.SDK_INT).append('\n');text.append("Uptime: ").append(SystemClock.elapsedRealtime()/60000).append(" minute\n\n");
        Intent battery=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null){int percent=battery.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100/Math.max(1,battery.getIntExtra(BatteryManager.EXTRA_SCALE,100));text.append("Baterie: ").append(percent).append("% · ").append(battery.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)==0?"pe baterie":"încărcare").append('\n');text.append("Temperatură: ").append(battery.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f).append(" °C\n");}
        ActivityManager am=(ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE);ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();am.getMemoryInfo(memory);text.append("RAM disponibilă: ").append(memory.availMem/1048576).append(" / ").append(memory.totalMem/1048576).append(" MiB\n");try{Debug.MemoryInfo[] own=am.getProcessMemoryInfo(new int[]{android.os.Process.myPid()});text.append("Proces Leo PSS: ").append(own[0].getTotalPss()/1024).append(" MiB\n");}catch(RuntimeException ignored){}
        text.append("Presiune RAM: ").append(memory.lowMemory?"ridicată":"normală").append("\n\n");appendStorage(text,"Date interne",Environment.getDataDirectory());for(Map.Entry<String,File> entry:LeoFileProvider.roots(c).entrySet())if(!entry.getKey().equals("leo"))appendStorage(text,entry.getKey().equals("phone")?"Fișiere telefon":"Card SD",entry.getValue());
        text.append('\n').append(sims).append('\n');WifiManager wifi=(WifiManager)c.getApplicationContext().getSystemService(Context.WIFI_SERVICE);text.append("Wi-Fi: ").append(wifi==null?"indisponibil":wifi.isWifiEnabled()?"pornit":"oprit").append('\n');text.append("Placă audio: ").append(PlaybackService.hardwareReady()?"prezentă":"indisponibilă").append('\n');AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);text.append("Volum muzică: ").append(audio.getStreamVolume(AudioManager.STREAM_MUSIC)).append('/').append(audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)).append("\n\n");text.append(UiMetrics.snapshot()).append("\n\nRaport cu câmpuri limitate; fără date personale sau logcat.\n");return text.toString();}
    private static void appendStorage(StringBuilder text,String label,File root){try{StatFs stat=new StatFs(root.getPath());text.append(label).append(": ").append(stat.getAvailableBytes()/1048576).append(" / ").append(stat.getTotalBytes()/1048576).append(" MiB liberi\n");}catch(RuntimeException ignored){text.append(label).append(": indisponibil\n");}}
    private void export(){if(report.isEmpty())return;final String snapshot=report;worker.execute(new Runnable(){public void run(){try{File directory=new File(getFilesDir(),"documents");if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException();android.util.AtomicFile file=new android.util.AtomicFile(new File(directory,"leo-diagnostic.txt"));FileOutputStream output=null;try{output=file.startWrite();output.write(snapshot.getBytes("UTF-8"));file.finishWrite(output);}catch(IOException e){if(output!=null)file.failWrite(output);throw e;}ui(new Runnable(){public void run(){notice("Salvat: Fișiere Leo → Documente Leo → leo-diagnostic.txt");}});}catch(IOException e){ui(new Runnable(){public void run(){notice("Raportul nu a putut fi salvat");}});}}});}
}
